@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="Content" @bind:event="oninput" rows="15" style="width: 100%;"></textarea>

<div style="margin-top: 0.5rem; display: flex; gap: 0.5rem; align-items: center;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSaved is not null)
    {
        <span>Last saved at @_lastSaved.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string Content { get; set; } = string.Empty;
    private DateTime? _lastSaved;
    private NotepadInterop? _interop;
    private Timer? _autoSaveTimer;
    private string _lastSavedContent = string.Empty;

    [Inject] private IJSRuntime JS { get; set; } = default!;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            var restored = await _interop.LoadAsync();
            if (restored is not null)
            {
                Content = restored;
                _lastSavedContent = restored;
                StateHasChanged();
            }

            _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async void AutoSaveCallback(object? state)
    {
        await InvokeAsync(async () =>
        {
            await SaveAsync();
            StateHasChanged();
        });
    }

    private async Task SaveNowAsync() => await SaveAsync();

    private async Task SaveAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(Content);
        _lastSaved = DateTime.Now;
        _lastSavedContent = Content;

        var hasUnsaved = !string.Equals(Content, _lastSavedContent, StringComparison.Ordinal);
        await _interop.SetBeforeUnloadAsync(hasUnsaved);
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        Content = string.Empty;
        _lastSavedContent = string.Empty;
        _lastSaved = null;
        await _interop.ClearAsync();
        await _interop.SetBeforeUnloadAsync(false);
    }

    private bool HasUnsavedChanges =>
        !string.Equals(Content, _lastSavedContent, StringComparison.Ordinal);

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
            await _autoSaveTimer.DisposeAsync();

        if (_interop is not null)
            await _interop.DisposeAsync();
    }
}

const STORAGE_KEY = 'notepad-content';

let beforeUnloadHandler = null;

export function initialize() {
    // Clean state on init
    removeBeforeUnload();
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
    removeBeforeUnload();
}

export function setBeforeUnload(enabled) {
    if (enabled) {
        if (!beforeUnloadHandler) {
            beforeUnloadHandler = (e) => {
                e.preventDefault();
                e.returnValue = '';
            };
            window.addEventListener('beforeunload', beforeUnloadHandler);
        }
    } else {
        removeBeforeUnload();
    }
}

function removeBeforeUnload() {
    if (beforeUnloadHandler) {
        window.removeEventListener('beforeunload', beforeUnloadHandler);
        beforeUnloadHandler = null;
    }
}

export function dispose() {
    removeBeforeUnload();
